"use client";
import { useState } from "react";
import { ApiClient } from "../../../apiClient/apiClient";

const FavoriteButton = ({ apartmentId, isInitiallyFavorited }) => {
  const [isFavorited, setIsFavorited] = useState(isInitiallyFavorited);
  const apiClient = new ApiClient();

  const toggleFavorite = async () => {
    try {
      if (isFavorited) {
        await apiClient.removeFavorite(apartmentId);
      } else {
        await apiClient.addFavorite(apartmentId);
      }
      setIsFavorited(!isFavorited);
    } catch (error) {
      console.error("Failed to toggle favorite:", error);
    }
  };

  return (
    <button
      onClick={toggleFavorite}
      title={isFavorited ? "Remove from favorites" : "Add to favorites"}
      className={`text-2xl focus:outline-none transition-colors duration-200 ${
        isFavorited ? "text-red-500" : "text-gray-300 hover:text-gray-500"
      }`}
    >
      {isFavorited ? "❤️" : "🤍"}
    </button>
  );
};

export default FavoriteButton;
